import React, { type ReactElement, type ReactNode, useMemo } from 'react';
import { isElement } from 'react-is';

export type DataTableV2Slots = {
  pagination: ReactNode | null;
  userActions: ReactElement | null;
  toolbar: ReactNode | null;
  expandableRowTemplate:
    | ((props: { row: Record<string, any> }) => JSX.Element) // eslint-disable-line @typescript-eslint/no-explicit-any
    | null;
};

export function useDataTableV2Slots(children: ReactNode): DataTableV2Slots {
  return useMemo(() => {
    const slots: DataTableV2Slots = {
      pagination: null,
      userActions: null,
      toolbar: null,
      expandableRowTemplate: null,
    };

    React.Children.forEach(children, (child) => {
      if (isElement(child)) {
        // TODO: Check for specific types of the slot children and return them back.
      }
    });
    return slots;
  }, [children]);
}
